import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.BveOjhN0.js";const y=JSON.parse('{"title":"Payroll — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payroll — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/payroll"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payroll — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/payroll"}]]},"headers":[],"relativePath":"user-guide/payroll.md","filePath":"user-guide/payroll.md","lastUpdated":1785695647000}'),l={name:"user-guide/payroll.md"};function n(s,e,i,p,c,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="payroll-—-user-guide" tabindex="-1">Payroll — User Guide <a class="header-anchor" href="#payroll-—-user-guide" aria-label="Permalink to &quot;Payroll — User Guide&quot;">​</a></h1><p>Enable <strong>Employees</strong> first, then install <strong>Payroll</strong> from Marketplace (free). For journal posting, also install <strong>Accounting</strong>. Nav appears under <strong>HR</strong>.</p><h2 id="payroll-profiles" tabindex="-1">Payroll profiles <a class="header-anchor" href="#payroll-profiles" aria-label="Permalink to &quot;Payroll profiles&quot;">​</a></h2><ol><li>Open <strong>Payroll profiles</strong> (or Payroll → Profiles).</li><li>Create one profile per employee: base salary, currency (default USD), pay frequency (monthly / biweekly / weekly), optional effective-from date and notes.</li><li>Only <strong>active</strong> employees with a profile are included when you create a pay run.</li></ol><h2 id="pay-runs" tabindex="-1">Pay runs <a class="header-anchor" href="#pay-runs" aria-label="Permalink to &quot;Pay runs&quot;">​</a></h2><ol><li>Create a pay run with period start and end dates.</li><li>The system generates a line per active employee profile (gross = base salary, adjustments = 0, net = gross).</li><li>While <strong>draft</strong>, edit period notes and line gross/adjustments (net recalculates).</li><li><strong>Approve</strong> (requires at least one line) → <strong>Pay</strong> to mark paid.</li><li>Optionally <strong>Post</strong> to Accounting (approved or paid) to create a draft journal for the net total.</li></ol><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>draft → approved → paid</span></span></code></pre></div><p>Only drafts are editable or soft-deletable. Posting requires the Accounting module and active expense + liability accounts (or explicit account ids).</p>',9)])])}const g=a(l,[["render",n]]);export{y as __pageData,g as default};
